// 2.   $\hat x_0 \leftarrow \mathrm{net}(x_t/s_t, \sigma_t)$
// 3.   $g_{dps} \leftarrow \nabla_{x_t} \hat x_0 \cdot \nabla_{\hat x_0}\|A\hat x_0 - y\|^2$
// 4.   $m_{dps} \leftarrow \beta\, m_{dps} + (1-\beta)\,g_{dps}$
// 5.   $\tilde x_0 \leftarrow \hat x_0$; for $k=1\ldots K$: $\tilde x_0 \leftarrow \tilde x_0 - \eta\, \nabla_{\tilde x_0}\|A\tilde x_0 - y\|^2$ (with grad-norm clip)
// 6.   $m_{prox} \leftarrow \beta\, m_{prox} + (1-\beta)(\tilde x_0 - \hat x_0)$
// 7.   $w_\sigma \leftarrow (1+\sigma)^{-p}$;   $\hat x_0' \leftarrow \hat x_0 + \lambda_p\, w_\sigma\, m_{prox}$
// 8.   apply SDE/ODE step using score $(\hat x_0' - x_t/s_t)/(\sigma^2 s_t)$, then $x_{t-1} \mathrel{-}= \lambda_{dps}\, m_{dps}$
// 9.   if inpaint mask $M$: $x_{t-1} \leftarrow (1-M)\,x_{t-1} + M(w\, y + (1-w)\,x_{t-1})$

// 1. for diffusion step $i = 1 \ldots N$ do
// 2.   $\hat x_0 \leftarrow \mathrm{net}(x_t/s_t, \sigma_t)$
// 3.   $z \leftarrow \hat x_0$
// 4.   for $k = 1 \ldots K$: compute $g, \ell = \mathrm{forward\_op.gradient}(z, y)$; $z \leftarrow z - \eta\,(0.5 g/\sqrt{\ell} + \lambda_{prox}(z - \hat x_0))$
// 5.   $\mathcal{L}_{proxy} \leftarrow \|\hat x_0 - z\|^2 / (2 K \eta)$
// 6.   $g_t \leftarrow \nabla_{x_t} \mathcal{L}_{proxy}$ (i.e. backprop through $\mathrm{net}$)
// 7.   $m \leftarrow \mu m + (1-\mu) g_t$;  $\hat m \leftarrow m / (1 - \mu^{i+1})$
// 8.   apply standard SDE/ODE step, then $x_{t-1} \mathrel{-}= \lambda\, \hat m$

// 1. for diffusion step $i = 1 \ldots N$ do
// 2.   $\hat x_0 \leftarrow \mathrm{net}(x_t/s_t, \sigma_t)$;  $r \leftarrow \|x_t/s_t - \hat x_0\|/\|\hat x_0\|$
// 3.   gate $\leftarrow \mathrm{clip}\big(1/(1+r^p) + b, 0, 1\big)$
// 4.   $x_{mix} \leftarrow \hat x_0 + \alpha (x_t/s_t - \hat x_0)$
// 5.   $g \leftarrow \mathrm{gate}\cdot \nabla\|A\hat x_0 - y\|^2 + (1-\mathrm{gate})\cdot \nabla\|A x_{mix} - y\|^2$
// 6.   $\ell \leftarrow \mathrm{gate}\cdot \ell_{\hat x} + (1-\mathrm{gate})\cdot \ell_{mix}$
// 7.   $b_t \leftarrow \nabla_{x_t} \hat x_0 \cdot g$;  rescale $b_t$ so $\|b_t\|/\|g\|\le c_1$, then clip $\|b_t\|\le c_2$
// 8.   $g_{ll} \leftarrow 0.5\, b_t \cdot \frac{\mathrm{gate}}{(1+r)\sqrt{\ell}}$
// 9.   apply SDE step (with optional churn $\kappa$ on $\epsilon$) using the prior score, then $x_{t-1} \mathrel{-}= \lambda\, g_{ll}$, clip to $[-1.25, 1.25]$

// 1. for diffusion step $i = 1 \ldots N$ do
// 2.   $\hat x_0 \leftarrow \mathrm{net}(x_t/s_t, \sigma_t)$;  $r \leftarrow x_t/s_t - \hat x_0$;  $\hat r \leftarrow r/\|r\|$
// 3.   $g \leftarrow \nabla_{x_t} \hat x_0 \cdot \nabla\|A\hat x_0 - y\|^2$
// 4.   $g_\parallel \leftarrow (g\cdot \hat r)\,\hat r$;  $g \leftarrow (g - g_\parallel) + (1-w_m)\,g_\parallel$
// 5.   $c \leftarrow 1/(1 + \|r\|/\sigma)^q$  // confidence weight
// 6.   $g \leftarrow 0.5\, g\, c\, /\sqrt{\ell}$
// 7.   $m \leftarrow \mu m + (1-\mu)\, g$
// 8.   apply standard SDE/ODE step, then $x_{t-1} \mathrel{-}= \lambda\, m$

// 1. initialize $\ell_{ref} \leftarrow 1$
// 2. for diffusion step $i = 1 \ldots N$ do
// 3.   $\hat x_0 \leftarrow \mathrm{net}(x_t/s_t, \sigma_t)$
// 4.   $g, \ell \leftarrow \mathrm{forward\_op.gradient}(\hat x_0, y)$
// 5.   if first step: $\ell_{ref} \leftarrow \overline{\ell}$  else  $\ell_{ref} \leftarrow \beta\, \ell_{ref} + (1-\beta)\,\overline{\ell}$;   $\ell_{ref} \leftarrow \max(\ell_{ref}, 10^{-6})$
// 6.   $g_t \leftarrow \nabla_{x_t} \hat x_0 \cdot g$;  zero out NaN/Inf
// 7.   $g_t \leftarrow 0.5\, g_t / \sqrt{\ell_{ref}}$
// 8.   apply standard SDE/ODE step, then $x_{t-1} \mathrel{-}= \lambda\, g_t$
